    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let remaining = post_residual as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Prefer placements that leave residue in a useful capacity class.
    let dead_space_penalty = if post_residual > 0 && post_residual < item {
        (item - post_residual) as f64
    } else {
        0.0
    };
    score += dead_space_penalty * 1.35;

    // A residue below the next item is harder to use; harmonic weighting makes
    // especially small residues more costly than merely awkward ones.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual < next_item_size {
            let deficit = next - remaining;
            score += deficit / (1.0 + post_residual as f64);
        } else {
            score -= (remaining / next).min(3.0);
        }
    } else {
        // At the stream tail, retain space for still-unseen small items.
        score += (remaining / capacity) * 1.1;
    }

    // Prefer residues that are multiples of common item-size classes, while
    // avoiding an excessive preference for one exact size.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.08;
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 0.35;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 0.25;
    }

    // Reward fitting into a tight bin, but do not make tiny residues dominate.
    let fill_ratio = item / residual.max(1.0);
    score -= (fill_ratio - 1.0).min(2.0) * 0.45;

    // Lookahead synergy: a residue just below the next item is attractive,
    // whereas a large post-residue suggests postponing a good fit.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (next - remaining).abs();
        score -= gap / (next + 1.0) * 0.8;
        if remaining >= next && remaining < next + 10 {
            score -= 0.6;
        }
    }

