    // Prefer fills that leave a useful amount of space, but avoid creating
    // tiny unusable fragments.
    let waste_penalty = if post > 0.0 && post < size {
        (size - post) * 1.8
    } else {
        0.0
    };
    score += waste_penalty;

    // A new bin is attractive when it avoids leaving an awkward gap and when
    // the current item is large relative to the average open-bin residual.
    if is_new_bin {
        score += 16.0;
        score += 22.0 * (mean - size).max(0.0) / capacity;
        score += 14.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Existing bins receive a stronger preference than opening a new one.
        score -= 12.0;

        // Tightly fitting placements are especially valuable.
        let fit_slack = (residual - size).max(0.0);
        score += 0.42 * fit_slack;

        // Prefer residuals close to the next item's size, when known.
        if next_item_size > 0 {
            let next = next_item_size as f64;
            let mismatch = (post - next).abs();
            score += 0.12 * mismatch;

            // A residual just below the next item can become dead space.
            if post < next && post > 0.0 {
                score += 0.20 * (next - post);
            }
        }

        // Near the end of the stream, use global occupancy more strongly.
        let occupancy = if open_bins_count == 0 {
            0.0
        } else {
            mean / capacity
        };
        score += 18.0 * occupancy * (1.0 - progress);
        score -= 10.0 * progress * (1.0 - occupancy);

        // If this is the last fitting bin, preserve it for an exact/near fit.
        if fitting_bins_count == 1 {
            score += 8.0 * progress;
            if next_item_size > 0 && post < next_item_size as f64 {
                score += 5.0;
            }
        }
    }

    // Small nonlinear preference for balanced residuals and a mild horizon
    // adjustment reflecting the cost of opening another bin.
    if !is_new_bin {
        let balance = (post - capacity * 0.5).abs() / capacity;
        score += 5.0 * balance * balance;
        score -= 3.0 * progress * (post / capacity);
    }

